
/* landing page: light-cloud portrait */
(function () {
const site=document.getElementById('site'),stage=document.getElementById('stage'),cv=document.getElementById('cv'),ctx=cv.getContext('2d');
const BG='#2A2C82',COUNT=34000,CUT=.18,FADE=.18,SIZE=1.1,AMB=.32;
let CW=0,CH=0,DPR=1,pts=null,N=0,iw=1,ih=1;
let tx=.5,ty=.5,cx=.5,cy=.5,hasPtr=false,lastPtr=0,t0=performance.now();
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;

function rng(s){return()=>{s|=0;s=s+0x6D2B79F5|0;let r=Math.imul(s^s>>>15,1|s);r=r+Math.imul(r^r>>>7,61|r)^r;return((r^r>>>14)>>>0)/4294967296}}

function setup(img){
  const m=Math.min(1,720/img.naturalWidth,960/img.naturalHeight);
  iw=Math.max(2,Math.round(img.naturalWidth*m));ih=Math.max(2,Math.round(img.naturalHeight*m));
  const o=document.createElement('canvas');o.width=iw;o.height=ih;
  const c=o.getContext('2d',{willReadFrequently:true});c.drawImage(img,0,0,iw,ih);
  const d=c.getImageData(0,0,iw,ih).data,n=iw*ih;
  const lm=new Uint8Array(n),fg=new Uint8Array(n);
  let alpha=false;
  for(let i=0;i<n;i++){lm[i]=.299*d[i*4]+.587*d[i*4+1]+.114*d[i*4+2];if(d[i*4+3]<250)alpha=true}
  if(alpha){for(let i=0;i<n;i++)fg[i]=d[i*4+3]>128?1:0}
  else{
    // plain background: take the edge colour, then flood in from the edges
    const ed=[];for(let x=0;x<iw;x++)ed.push(x);for(let y=1;y<ih;y++)ed.push(y*iw,y*iw+iw-1);
    const med=ch=>{const v=ed.map(i=>d[i*4+ch]).sort((p,q)=>p-q);return v[v.length>>1]};
    const br=med(0),bgc=med(1),bb=med(2),tol=3600;
    const near=i=>{const p=d[i*4]-br,q=d[i*4+1]-bgc,s=d[i*4+2]-bb;return p*p+q*q+s*s<tol};
    fg.fill(1);const st=[];
    for(const i of ed)if(fg[i]&&near(i)){fg[i]=0;st.push(i)}
    while(st.length){
      const i=st.pop(),x=i%iw;
      if(x>0&&fg[i-1]&&near(i-1)){fg[i-1]=0;st.push(i-1)}
      if(x<iw-1&&fg[i+1]&&near(i+1)){fg[i+1]=0;st.push(i+1)}
      if(i>=iw&&fg[i-iw]&&near(i-iw)){fg[i-iw]=0;st.push(i-iw)}
      if(i<n-iw&&fg[i+iw]&&near(i+iw)){fg[i+iw]=0;st.push(i+iw)}
    }
  }
  let cnt=0;for(let i=0;i<n;i++)cnt+=fg[i];
  if(cnt<n*.03){fg.fill(1);cnt=n}
  const hist=new Uint32Array(256);
  for(let i=0;i<n;i++)if(fg[i])hist[lm[i]]++;
  let acc=0,lo=0,hi=255;
  for(let i=0;i<256;i++){acc+=hist[i];if(acc>cnt*.02){lo=i;break}}
  acc=0;for(let i=255;i>=0;i--){acc+=hist[i];if(acc>cnt*.02){hi=i;break}}
  const span=Math.max(1,hi-lo),r=rng(11);
  const px=new Float32Array(COUNT),py=new Float32Array(COUNT),pl=new Float32Array(COUNT),pp=new Float32Array(COUNT),pz=new Float32Array(COUNT);
  // centre of the subject, so the edge fade and depth follow the person, not the frame
  let sxm=0,sym=0;for(let i=0;i<n;i+=7)if(fg[i]){sxm+=i%iw;sym+=(i/iw|0)}
  let cn=0;for(let i=0;i<n;i+=7)cn+=fg[i];
  const mcx=cn?sxm/cn/iw:.5,mcy=cn?sym/cn/ih:.5;
  N=0;
  for(let k=0;k<COUNT*14&&N<COUNT;k++){
    const x=r()*iw,y=r()*ih,i=(y|0)*iw+(x|0);
    if(!fg[i])continue;
    let l=Math.min(1,Math.max(0,(lm[i]-lo)/span));
    const dx=(x/iw-mcx)*2,dy=(y/ih-mcy)*2,e=Math.min(1,Math.hypot(dx,dy));
    l*=1-FADE*e*e*e;
    if(l<CUT)continue;
    if(r()<Math.pow(l,1.3)){px[N]=x/iw;py[N]=y/ih;pl[N]=l;pp[N]=r()*6.283;pz[N]=(l-.5)*.5+(1-e*e)*.6;N++}
  }
  pts={px,py,pl,pp,pz};
  t0=performance.now();
}
function fromSrc(src){
  const im=new Image();
  im.onload=()=>setup(im);
  im.src=src;
}
fromSrc('data:image/png;base64,');

function resize(){
  DPR=Math.min(2,window.devicePixelRatio||1);
  CW=cv.width=Math.round(site.clientWidth*DPR);CH=cv.height=Math.round(site.clientHeight*DPR);
}
addEventListener('resize',resize);resize();

// pointer position as a fraction of the canvas itself, so the light and the trail stay under the cursor even when the hero is scrolled
function setPtr(e,add){const r=cv.getBoundingClientRect();tx=(e.clientX-r.left)/r.width;ty=(e.clientY-r.top)/r.height;hasPtr=true;lastPtr=performance.now();}
addEventListener('pointermove',e=>setPtr(e,true));
addEventListener('pointerdown',e=>setPtr(e,false));
document.addEventListener('pointerleave',()=>{hasPtr=false});

const NB=16,paths=[];
let hx=CW*.5,hy=CH*.5,pmx=0,pmy=0,lastT=performance.now();
function frame(now){
  requestAnimationFrame(frame);
  const dt=Math.min(.05,(now-lastT)/1000);lastT=now;
  ctx.fillStyle=BG;ctx.fillRect(0,0,CW,CH);
  if(!pts)return;
  const time=(now-t0)/1000;
  // light follows the pointer with a soft spring, or drifts slowly when idle
  let gx=tx*CW,gy=ty*CH;
  if(!hasPtr||now-lastPtr>4000){gx=(.5+.3*Math.sin(time*.45))*CW;gy=(.48+.24*Math.sin(time*.65+1.1))*CH}
  const k=reduce?1:1-Math.exp(-dt*7);
  hx+=(gx-hx)*k;hy+=(gy-hy)*k;
  // very slight 3D shift: the cloud turns a touch toward the light
  const kp=reduce?0:1-Math.exp(-dt*2.5);
  pmx+=((hx/CW-.5)*2-pmx)*kp;pmy+=((hy/CH-.5)*2-pmy)*kp;
  const big=Math.max(CW,CH),sg=big*.07,invS=1/(2*sg*sg),cut2=9*sg*sg,sb=big*.26,invB=1/(2*sb*sb);
  const s=Math.min(CH/ih,CW/iw*1.6),dw=iw*s,dh=ih*s,ox=(CW-dw)/2,oy=CH-dh;
  const intro=Math.min(1,time/1.8),ie=intro*intro*(3-2*intro);
  const sz=SIZE*DPR*Math.max(.8,Math.min(1.6,dh/900/DPR*1.1+.2));
  const amp=dh*.012;
  for(let b=0;b<NB;b++)paths[b]=new Path2D();
  const {px,py,pl,pp,pz}=pts,tw=time*1.1;
  for(let i=0;i<N;i++){
    const z=pz[i]-.3;
    const x=ox+px[i]*dw+pmx*z*amp,y=oy+py[i]*dh+pmy*z*amp*.7;
    const dx=x-hx,dy=y-hy,d2=dx*dx+dy*dy;
    const g=.1*Math.exp(-d2*invB)+(d2<cut2?.8*Math.exp(-d2*invS):0);
    let b=pl[i]*(AMB+g)*(1+.06*Math.sin(tw+pp[i]))*ie;
    if(b>1)b=1;
    const q=(b*NB)|0;if(q<1)continue;
    paths[q>=NB?NB-1:q].rect(x-sz/2,y-sz/2,sz,sz);
  }
  ctx.fillStyle='#fff';
  for(let q=1;q<NB;q++){ctx.globalAlpha=q/(NB-1);ctx.fill(paths[q])}
  // small soft light dot at the cursor, no trail
  const R=14*DPR,gr=ctx.createRadialGradient(hx,hy,0,hx,hy,R);
  gr.addColorStop(0,'rgba(255,255,255,.72)');gr.addColorStop(1,'rgba(255,255,255,0)');
  ctx.globalCompositeOperation='lighter';ctx.globalAlpha=ie;ctx.fillStyle=gr;
  ctx.beginPath();ctx.arc(hx,hy,R,0,6.283);ctx.fill();
  ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
}
requestAnimationFrame(frame);

// typed role words: type, pause, backspace, repeat, with a blinking caret. Starts only when the page is fully open.
const typed=document.getElementById('typed'),caret=document.getElementById('caret'),cyc=document.getElementById('cyc');
const words=['Strategist','Director','Technologist'];
let run=0;
function measure(){
  let max=0;
  for(const w of words){
    const m=document.createElement('span');m.className='measure';m.textContent=w;cyc.appendChild(m);
    max=Math.max(max,m.offsetWidth);m.remove();
  }
  cyc.style.width=Math.ceil(max+8)+'px';
}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function loop(id){
  const alive=()=>id===run;
  typed.textContent='';caret.classList.remove('solid');
  await sleep(900);
  let w=0;
  while(alive()){
    const word=words[w%words.length];
    if(reduce){typed.textContent=word;await sleep(2600);w++;continue}
    caret.classList.add('solid');
    for(let i=1;i<=word.length&&alive();i++){typed.textContent=word.slice(0,i);await sleep(75+Math.random()*75)}
    if(!alive())return;
    caret.classList.remove('solid');
    await sleep(2100);
    if(!alive())return;
    caret.classList.add('solid');
    for(let i=word.length-1;i>=0&&alive();i--){typed.textContent=word.slice(0,i);await sleep(36+Math.random()*24)}
    if(!alive())return;
    caret.classList.remove('solid');
    await sleep(420);
    w++;
  }
}
let started=false;
site.addEventListener('sitefull',e=>{
  if(!e.detail||started)return;
  started=true;measure();loop(++run);
});
(document.fonts&&document.fonts.ready?document.fonts.ready:Promise.resolve()).then(measure);
addEventListener('resize',measure);

})();
